(()=>{const oldHome=home;home=function(){OnlineRooms.cancel();oldHome();};const params=new URLSearchParams(location.search),code=params.get('room'),game=params.get('game');if(!code||!['pokemon','keepup','burrinho'].includes(game))return;history.replaceState(null,'',location.pathname);if(game==='pokemon')PokemonOnlineInvite(code);else if(game==='burrinho')BurrinhoOnlineInvite(code);else KeepupOnlineInvite(code);})();
